        if not isinstance(key, tuple):
            raise ValueError('Invalid call for scalar access (setting)!')
        if len(key) != self.obj.ndim:
            raise ValueError('Not enough indexers for scalar access (setting)!')
        key = self._convert_key(key)
        key.append(value)
